-- Public reads disclose only visible published data and keep archived QR links useful.
select no_plan();
select tests.create_range_fixture();
reset role;
select tests.act_as_public();
select throws_ok('select * from public.store_prices','42501',null,'public cannot read raw store prices');
select throws_ok('select * from public.show_store_status','42501',null,'public cannot read raw show pricing');
-- The local database image segfaults on a denied direct function call; check its live ACL.
-- Public table/view and retailer RPC denials still execute as the actual API personas.
select ok(not has_function_privilege(current_user,'private.product_playback(uuid)','execute'),'internal playback helper is not a public capability');
select is(public.resolve_qr('fixture-1')->>'target_type','show','public QR resolves published retailer show');
select is(public.resolve_qr('missing'),null::jsonb,'unknown QR returns null');
select is(jsonb_array_length(public.store_page('90000000-0000-0000-0000-000000000001')->'products'),1,'store page includes visible published range');
select ok(not (public.store_page('90000000-0000-0000-0000-000000000001')->'store' ? 'licence'),'public store omits private licence');
select ok(not (public.store_page('90000000-0000-0000-0000-000000000001')->'organisation' ? 'onboarding'),'public organisation omits onboarding data');
select is(public.show_for_store('93000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000002'),null::jsonb,'show cannot cross store tenant');
select is(public.show_for_store('93000000-0000-0000-0000-000000000003','90000000-0000-0000-0000-000000000001'),null::jsonb,'private shopper show is not public retailer playback');
select is(public.show_for_store('93000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001')#>>'{products,0,product,effects,0,version_id}','50000000-0000-0000-0000-000000000001','playback uses current effect version');
select is(public.show_for_store('93000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001')->>'price_minor','2500','public price uses retailer default');
reset role;
select tests.act_as('platform_staff');
select lives_ok($test$select public.create_effect_draft('40000000-0000-0000-0000-000000000001','published-effect','Published fixture','peony',tests.design_fixture(),'new-renderer')$test$,'editor creates replacement design');
select lives_ok($test$select public.publish_effect_version((select draft_version_id from public.effects where id = '40000000-0000-0000-0000-000000000001'))$test$,'editor publishes replacement design');
reset role;
select tests.act_as_public();
select is(public.show_for_store('93000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001')#>>'{products,0,product,effects,0,renderer}','new-renderer','saved show plays latest effect without cue changes');
reset role;
select tests.act_as('platform_staff');
select lives_ok($test$select public.create_product_draft('60000000-0000-0000-0000-000000000001','published-product','Published product','cake',tests.composition_fixture(),'{"a":"40000000-0000-0000-0000-000000000001"}')$test$,'editor creates replacement product');
select lives_ok($test$select public.publish_product_version((select draft_version_id from public.products where id = '60000000-0000-0000-0000-000000000001'))$test$,'editor publishes replacement product');
reset role;
select ok(public.show_for_store('93000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001')#>>'{products,0,product,version_id}' <> '70000000-0000-0000-0000-000000000001','saved show plays latest product composition');
update public.qr_codes set status = 'archived'  where slug = 'fixture-1';
select tests.act_as_public();
select is(public.resolve_qr('fixture-1')->>'target_type','store','archived QR falls back to store');
select is(public.resolve_qr('fixture-1')->'target_id','null'::jsonb,'archived QR does not return old target');
reset role;
update public.qr_codes set status = 'paused' where slug = 'fixture-1';
select tests.act_as_public();
select is(public.resolve_qr('fixture-1')->>'target_type','store','paused QR falls back to store');
reset role;
update public.qr_codes set status = 'live' where slug = 'fixture-1';
update public.store_items set hidden = true where store_id = '90000000-0000-0000-0000-000000000001';
select tests.act_as_public();
select is(jsonb_array_length(public.store_page('90000000-0000-0000-0000-000000000001')->'products'),0,'hidden store product is omitted');
select is(public.show_for_store('93000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001'),null::jsonb,'hidden product prevents design leakage');
select is(public.resolve_qr('fixture-1')->>'target_type','store','unavailable show target falls back');
reset role;
update public.store_items set hidden = false where store_id = '90000000-0000-0000-0000-000000000001';
insert into public.stock_movements(organisation_id,store_id,range_item_id,delta,qty_after,source)
  values ('10000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000001',-10,0,'csv');
select tests.act_as_public();
select is(public.show_for_store('93000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001')->>'available','false','stock availability is returned without reserving');
reset role;
insert into public.qr_codes(organisation_id,slug,target_type)
  values ('10000000-0000-0000-0000-000000000001','organisation-fixture','planner');
select tests.act_as_public();
select is(public.resolve_qr('organisation-fixture')->>'pick_store','true','organisation QR asks for a store');
select is(jsonb_array_length(public.resolve_qr('organisation-fixture')->'stores'),1,'organisation QR offers only its stores');
reset role;
update public.stores set status = 'closed' where id = '90000000-0000-0000-0000-000000000001';
select tests.act_as_public();
select is(public.store_page('90000000-0000-0000-0000-000000000001'),null::jsonb,'closed store is unavailable');
select is(public.resolve_qr('fixture-1'),null::jsonb,'closed store QR is unavailable');
select is(jsonb_array_length(public.resolve_qr('organisation-fixture')->'stores'),0,'store picker excludes closed stores');
reset role;
update public.stores set status = 'open' where id = '90000000-0000-0000-0000-000000000001';
insert into public.collections(id,organisation_id,name,slug,kind,rule)
  values ('92000000-0000-0000-0000-000000000004','10000000-0000-0000-0000-000000000001','Smart quiet collection','smart-fixture','smart','{"max_price_minor":3000,"max_noise":2}');
select is(jsonb_array_length(public.store_page('90000000-0000-0000-0000-000000000001')#>'{collections,1,product_ids}'),1,'smart collection evaluates current store facts');
update public.store_items set price_override_minor = 4000 where store_id = '90000000-0000-0000-0000-000000000001';
select is(jsonb_array_length(public.store_page('90000000-0000-0000-0000-000000000001')#>'{collections,1,product_ids}'),0,'smart collection follows store price override');
select throws_ok($test$update public.collections set rule = '{"max_noise":"loud"}' where kind = 'smart'$test$,'23514',null,'unknown smart rule input is validated');
select is(public.resolve_qr('organisation-fixture')#>>'{stores,0,target_type}','planner','organisation code preserves per-store target');
update public.qr_codes set status = 'archived' where slug = 'organisation-fixture';
select is(public.resolve_qr('organisation-fixture')#>>'{stores,0,target_type}','store','archived organisation code routes picked stores to page');
reset role;
select tests.act_as('organisation_owner');
select lives_ok($test$insert into public.range_items(id,organisation_id,product_id,price_minor,currency) values ('91000000-0000-0000-0000-000000000004','10000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000003',5000,'GBP')$test$,'retailer adds pack to range');
select lives_ok($test$insert into public.store_items(organisation_id,store_id,range_item_id) values ('10000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001','91000000-0000-0000-0000-000000000004')$test$,'retailer makes pack visible at store');
select lives_ok($test$select public.save_show('93000000-0000-0000-0000-000000000001',tests.show_cues('60000000-0000-0000-0000-000000000003'),6000)$test$,'retailer saves pack cue');
reset role;
select tests.act_as_public();
select is(public.show_for_store('93000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001')#>>'{products,0,product,kind}','pack','public playback includes selection pack');
select is(public.show_for_store('93000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001')#>>'{products,0,product,pack_items,0,product,effects,0,renderer}','new-renderer','nested pack playback resolves current designs');
reset role;
update public.organisations set status = 'suspended' where id = '10000000-0000-0000-0000-000000000001';
select tests.act_as_public();
select is(public.store_page('90000000-0000-0000-0000-000000000001'),null::jsonb,'suspended retailer has no public page');
select is(public.resolve_qr('fixture-1'),null::jsonb,'suspended retailer has no public QR target');
select is(public.show_for_store('93000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000001'),null::jsonb,'suspended retailer has no public playback');
select finish();
